function writeSlot(k) { try { localStorage.setItem(k, snapshot()); return true; } catch (e) { return false; } }
function readSlot(k) { try { const raw = localStorage.getItem(k); return raw ? JSON.parse(raw) : null; } catch (e) { return null; } }
