    if (d < 7 && !P.dead) { const a = Math.atan2(dz, dx) + 1.2; tx = Math.cos(a); tz = Math.sin(a); sp = d > 3 ? 1.4 : -0.8; if (s.cd <= 0 && d < 6.5) { s.cd = 2.4; shootOrb(s.x, s.z, dx / (d || 1), dz / (d || 1), s.edmg); } }
