// ---------- borda irregular da floresta (chamado durante a geração: só usa constantes já existentes) ----------
function rimDepth(x, y) { return 2.5 + Math.max(0, fbm(x * 0.055, y * 0.055, 31) - 0.38) * 26 + (fbm(x * 0.21, y * 0.21, 37) - 0.5) * 2.4; }
