  const t = new Float32Array(W * H); for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) { const i = I(x, y); if (!L[i]) continue; let all = 1; for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) { const nx = x + dx, ny = y + dy; if (inb(nx, ny) && !L[I(nx, ny)]) all = 0; } t[i] = all; }
