  items.push(['new', 'sparkles', auto ? 'Novo jogo' : 'Começar', confirmNew ? 'Toque de novo para confirmar: o save automático será substituído' : auto ? 'Começar uma história nova' : 'Crie sua personagem e chegue ao vale']);
