  items.push(['set', 'wand', 'Opções', 'Som, gráficos e filtro']);
  items.push(['help', 'help', 'Como jogar', 'Controles e dicas']);
  items.push(['cred', 'heart', 'Créditos', 'Quem ajudou a fazer o vale']);
