  if (sd || sa || ss || sw || INPUT.stick) { keys.KeyD = sd; keys.KeyA = sa; keys.KeyS = ss; keys.KeyW = sw; INPUT.stick = sd || sa || ss || sw; } if (run || INPUT.run) { keys.ShiftLeft = run; INPUT.run = run; }
