  const A = [76, 0, 79, 76, 74, 72, 74, 0, 72, 0, 76, 72, 69, 0, 67, 0, 69, 72, 74, 72, 69, 0, 65, 67, 67, 0, 71, 74, 74, 72, 71, 0];
  const B = [79, 0, 81, 79, 76, 0, 74, 76, 72, 0, 76, 79, 81, 0, 79, 0, 77, 76, 74, 72, 69, 72, 74, 0, 74, 0, 72, 71, 72, 0, 0, 0];
